import{_ as e,c as r,o as a,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Military & Career","description":"","frontmatter":{"title":"Military & Career"},"headers":[],"relativePath":"general/military-and-career.md","filePath":"general/military-and-career.md","lastUpdated":null}'),l={name:"general/military-and-career.md"};function o(d,t,n,s,h,m){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="military-career" tabindex="-1">Military &amp; Career <a class="header-anchor" href="#military-career" aria-label="Permalink to &quot;Military &amp; Career&quot;">​</a></h1><p>Resources for leaving service, self-service portals, evaluations, awards, promotion boards, and career development for military personnel.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th></tr></thead><tbody><tr><td><a href="/general/leaving-service.html">Leaving Service</a></td><td>Transition assistance and civilian career guidance</td></tr><tr><td><a href="/general/ssc.html">SSC Quick Links</a></td><td>Self-service portals and common links</td></tr><tr><td><a href="/general/army-evaluation-resources.html">Army Evaluation Resources</a></td><td>OER/NCOER guides and tools</td></tr></tbody></table><h2 id="transitioning-out" tabindex="-1">Transitioning Out <a class="header-anchor" href="#transitioning-out" aria-label="Permalink to &quot;Transitioning Out&quot;">​</a></h2><h3 id="transition-assistance" tabindex="-1">Transition Assistance <a class="header-anchor" href="#transition-assistance" aria-label="Permalink to &quot;Transition Assistance&quot;">​</a></h3><ul><li><a href="/general/leaving-service.html">Leaving Service Guide</a> - Comprehensive transition guide</li><li><a href="https://forum.irregularchat.com/t/practical-tips-for-service-to-civilian-career/4780" target="_blank" rel="noreferrer">Practical Tips for Service to Civilian Career</a> - Community lessons learned</li></ul><h3 id="key-programs" tabindex="-1">Key Programs <a class="header-anchor" href="#key-programs" aria-label="Permalink to &quot;Key Programs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program</th><th>Description</th></tr></thead><tbody><tr><td><strong>TAP</strong></td><td>Transition Assistance Program - attend &quot;retiree&quot; version if eligible</td></tr><tr><td><strong>SkillBridge</strong></td><td>Up to 180 days civilian work experience during final service</td></tr><tr><td><strong>SOCOM Care Coalition</strong></td><td><a href="https://www.socom.mil/care-coalition/Pages/Career-Transition.aspx" target="_blank" rel="noreferrer">Career Transition Resources</a></td></tr></tbody></table><h3 id="skillbridge" tabindex="-1">SkillBridge <a class="header-anchor" href="#skillbridge" aria-label="Permalink to &quot;SkillBridge&quot;">​</a></h3><ul><li>Available during final 180 days of service</li><li>Requires commander approval (O6 memo for some branches)</li><li>Companies not on approved list can still participate with additional paperwork</li><li>See <a href="https://skillbridge.osd.mil/faq.htm" target="_blank" rel="noreferrer">SkillBridge FAQ</a> and <a href="https://skillbridge.osd.mil/industry-employers.htm" target="_blank" rel="noreferrer">Industry Employers</a></li></ul><h3 id="professional-guidance" tabindex="-1">Professional Guidance <a class="header-anchor" href="#professional-guidance" aria-label="Permalink to &quot;Professional Guidance&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Contact</th></tr></thead><tbody><tr><td>MilBridge Consulting</td><td>Noel McCall - <a href="mailto:NoelMcCall@milbridgeconsult.com" target="_blank" rel="noreferrer">NoelMcCall@milbridgeconsult.com</a></td></tr><tr><td>JANUS 101/Donovan Bank</td><td><a href="mailto:paul@donovanbank.org" target="_blank" rel="noreferrer">paul@donovanbank.org</a>, <a href="mailto:drew@donovanbank.org" target="_blank" rel="noreferrer">drew@donovanbank.org</a></td></tr><tr><td>The Honor Foundation</td><td><a href="http://honor.org" target="_blank" rel="noreferrer">honor.org</a></td></tr></tbody></table><h3 id="state-benefits-for-disabled-veterans" tabindex="-1">State Benefits for Disabled Veterans <a class="header-anchor" href="#state-benefits-for-disabled-veterans" aria-label="Permalink to &quot;State Benefits for Disabled Veterans&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Benefits</th></tr></thead><tbody><tr><td>Texas</td><td>Property tax exemptions, no state income tax</td></tr><tr><td>Illinois</td><td>Property tax exemptions, income tax waivers for military retirement</td></tr><tr><td>Florida</td><td>Property tax benefits, state education benefits</td></tr><tr><td>New Hampshire</td><td>Tax exemptions for adapted homes</td></tr><tr><td>Virginia</td><td>Up to $15,000 military pay exempt from state income tax</td></tr></tbody></table><h2 id="self-service-portals-ssc" tabindex="-1">Self-Service Portals (SSC) <a class="header-anchor" href="#self-service-portals-ssc" aria-label="Permalink to &quot;Self-Service Portals (SSC)&quot;">​</a></h2><h3 id="individual-army-links" tabindex="-1">Individual Army Links <a class="header-anchor" href="#individual-army-links" aria-label="Permalink to &quot;Individual Army Links&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Portal</th><th>Link</th></tr></thead><tbody><tr><td>Career</td><td>NCOERs</td><td><a href="https://evaluations.hrc.army.mil/" target="_blank" rel="noreferrer">evaluations.hrc.army.mil</a></td></tr><tr><td>Career</td><td>Promotion Points</td><td><a href="https://my.ippsa.army.mil/" target="_blank" rel="noreferrer">my.ippsa.army.mil</a></td></tr><tr><td>Career</td><td>MyBoardFile</td><td><a href="https://www.hrcapps.army.mil/Portal/" target="_blank" rel="noreferrer">hrcapps.army.mil</a></td></tr><tr><td>Career</td><td>Army Career Tracker</td><td><a href="https://actnow.army.mil/" target="_blank" rel="noreferrer">actnow.army.mil</a></td></tr><tr><td>Education</td><td>ATRRS</td><td><a href="https://www.atrrs.army.mil/atrrscc/search.aspx" target="_blank" rel="noreferrer">atrrs.army.mil</a></td></tr><tr><td>Education</td><td>ALMS</td><td><a href="https://www.lms.army.mil/" target="_blank" rel="noreferrer">lms.army.mil</a></td></tr><tr><td>Education</td><td>JKO</td><td><a href="https://jkodirect.jten.mil/Atlas2/page/login/Login.jsf" target="_blank" rel="noreferrer">jkodirect.jten.mil</a></td></tr><tr><td>Education</td><td>JSOU</td><td><a href="https://jsou.edu/" target="_blank" rel="noreferrer">jsou.edu</a></td></tr><tr><td>Education</td><td>ArmyIgnited</td><td><a href="http://www.armyignited.com" target="_blank" rel="noreferrer">armyignited.com</a></td></tr><tr><td>Self Service</td><td>IPPS-A</td><td><a href="https://my.ippsa.army.mil/" target="_blank" rel="noreferrer">my.ippsa.army.mil</a></td></tr><tr><td>Self Service</td><td>iPERMS</td><td><a href="https://iperms.hrc.army.mil/rms/record" target="_blank" rel="noreferrer">iperms.hrc.army.mil</a></td></tr><tr><td>Self Service</td><td>MyPay LES</td><td><a href="https://mypay.dfas.mil/mypay.aspx" target="_blank" rel="noreferrer">mypay.dfas.mil</a></td></tr><tr><td>Self Service</td><td>MEDPROS</td><td><a href="https://medpros.mods.army.mil/portal/" target="_blank" rel="noreferrer">medpros.mods.army.mil</a></td></tr><tr><td>Self Service</td><td>TRI-CARE</td><td><a href="https://my.mhsgenesis.health.mil/" target="_blank" rel="noreferrer">my.mhsgenesis.health.mil</a></td></tr><tr><td>Family</td><td>CAC/DEERs Renewal</td><td><a href="https://www.cac.mil/Next-Generation-Uniformed-Services-ID-Card/Renewing-Online/" target="_blank" rel="noreferrer">cac.mil</a></td></tr></tbody></table><h3 id="unit-work-links" tabindex="-1">Unit Work Links <a class="header-anchor" href="#unit-work-links" aria-label="Permalink to &quot;Unit Work Links&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Portal</th><th>Link</th></tr></thead><tbody><tr><td>DTMS</td><td><a href="https://dtms.army.mil/" target="_blank" rel="noreferrer">dtms.army.mil</a></td></tr><tr><td>DTS</td><td><a href="https://dtsproweb.defensetravel.osd.mil/dts-app/pubsite/all/view/" target="_blank" rel="noreferrer">dtsproweb.defensetravel.osd.mil</a></td></tr><tr><td>Army Pubs</td><td><a href="https://armypubs.army.mil/" target="_blank" rel="noreferrer">armypubs.army.mil</a></td></tr><tr><td>Joint Doctrine</td><td><a href="https://www.jcs.mil/Doctrine/" target="_blank" rel="noreferrer">jcs.mil/Doctrine</a></td></tr><tr><td>CALL</td><td><a href="https://www.army.mil/CALL" target="_blank" rel="noreferrer">army.mil/CALL</a></td></tr><tr><td>METL</td><td><a href="https://atn.army.mil/ATNPortalUI/METL/" target="_blank" rel="noreferrer">atn.army.mil/METL</a></td></tr></tbody></table><p>See: <a href="/general/ssc.html">SSC Quick Links</a> for complete list</p><h2 id="evaluations" tabindex="-1">Evaluations <a class="header-anchor" href="#evaluations" aria-label="Permalink to &quot;Evaluations&quot;">​</a></h2><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><a href="/general/army-evaluation-resources.html">Army Evaluation Resources</a> - Comprehensive guide</li><li><a href="/ai-ml/evaluation-ai-prompt.html">Evaluation AI Prompt</a> - AI assistance for drafting bullets</li></ul><h3 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Forms</th></tr></thead><tbody><tr><td>OER</td><td>DA 67-10-1A (Company Grade), DA 67-10-2 (Field Grade)</td></tr><tr><td>NCOER</td><td>DA 2166-9-1 (SGT), DA 2166-9-2 (SSG-1SG/MSG), DA 2166-9-3 (CSM-SGM)</td></tr><tr><td>AER</td><td>DA 1059 Series</td></tr><tr><td>Counseling</td><td>DA 4856</td></tr></tbody></table><h3 id="ai-tools" tabindex="-1">AI Tools <a class="header-anchor" href="#ai-tools" aria-label="Permalink to &quot;AI Tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://www.armified.com/" target="_blank" rel="noreferrer">Armified</a></td><td>Free templates and sample approaches</td></tr><tr><td><a href="https://rapidepr.com/" target="_blank" rel="noreferrer">RapidEPR</a></td><td>Multi-branch evaluation resource</td></tr><tr><td><a href="/ai-ml/evaluation-ai-prompt.html">AI Prompt Template</a></td><td>LLM prompt for drafting bullets</td></tr></tbody></table><h3 id="key-regulations" tabindex="-1">Key Regulations <a class="header-anchor" href="#key-regulations" aria-label="Permalink to &quot;Key Regulations&quot;">​</a></h3><ul><li>AR 623-3 - Evaluation Reporting System</li><li>DA PAM 623-3 - Evaluation Reporting System Guide</li></ul><h2 id="awards" tabindex="-1">Awards <a class="header-anchor" href="#awards" aria-label="Permalink to &quot;Awards&quot;">​</a></h2><ul><li><a href="/general/awards.html">Awards Guide</a> - Writing guidelines and templates</li><li><a href="/general/combined-awards.html">Combined Awards</a> - Extended awards reference</li><li><a href="/ai-ml/award-bullet-ai-prompt-template.html">Award Bullet AI Prompt</a> - AI assistance for bullets</li></ul><h3 id="key-points" tabindex="-1">Key Points <a class="header-anchor" href="#key-points" aria-label="Permalink to &quot;Key Points&quot;">​</a></h3><ol><li>Acronyms: Only use when appearing more than once</li><li>Numbers: Spell out 0-9, numerals for 10+</li><li>Ranks: Always abbreviate in achievement blocks</li><li>Explain: What they did AND how they did it</li></ol><p><strong>Regulation</strong>: <a href="https://armypubs.army.mil/epubs/DR_pubs/DR_a/ARN30935-AR_600-8-22-000-WEB-1.pdf" target="_blank" rel="noreferrer">AR 600-8-22 Military Awards</a></p><h2 id="promotion-boards" tabindex="-1">Promotion Boards <a class="header-anchor" href="#promotion-boards" aria-label="Permalink to &quot;Promotion Boards&quot;">​</a></h2><ul><li><a href="/general/promotion-boards.html">Promotion Boards Guide</a> - Preparation and Q&amp;A</li><li><a href="https://cascom.army.mil/asrp/slr/files/DoctrineSmartBookJuly2024.pdf" target="_blank" rel="noreferrer">Doctrine SmartBook</a> - Doctrine primer</li></ul><h3 id="key-regulations-to-know" tabindex="-1">Key Regulations to Know <a class="header-anchor" href="#key-regulations-to-know" aria-label="Permalink to &quot;Key Regulations to Know&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Regulation</th><th>Topic</th></tr></thead><tbody><tr><td>AR 600-20</td><td>Army Command Policy, EO, SHARP</td></tr><tr><td>AR 670-1</td><td>Uniform and Appearance</td></tr><tr><td>AR 600-85</td><td>Army Substance Abuse Program</td></tr><tr><td>AR 600-9</td><td>Army Body Composition Program</td></tr><tr><td>AR 600-8-19</td><td>Enlisted Promotions and Reductions</td></tr><tr><td>TC 3-21.5</td><td>Drill and Ceremony</td></tr><tr><td>TC 3-22.6</td><td>Guard Duty</td></tr></tbody></table><h3 id="seven-army-values-ldrship" tabindex="-1">Seven Army Values (LDRSHIP) <a class="header-anchor" href="#seven-army-values-ldrship" aria-label="Permalink to &quot;Seven Army Values (LDRSHIP)&quot;">​</a></h3><p>Loyalty, Duty, Respect, Selfless Service, Honor, Integrity, Personal Courage</p><h2 id="reserve-guard" tabindex="-1">Reserve &amp; Guard <a class="header-anchor" href="#reserve-guard" aria-label="Permalink to &quot;Reserve &amp; Guard&quot;">​</a></h2><ul><li><a href="/general/information-for-national-guard-and-reserve-service-members.html">Information for National Guard and Reserve Service Members</a></li></ul><h2 id="travel" tabindex="-1">Travel <a class="header-anchor" href="#travel" aria-label="Permalink to &quot;Travel&quot;">​</a></h2><ul><li><a href="/general/dts-sato-travel.html">DTS/SATO Travel</a> - Travel system guidance</li></ul><h2 id="business-entrepreneurship" tabindex="-1">Business &amp; Entrepreneurship <a class="header-anchor" href="#business-entrepreneurship" aria-label="Permalink to &quot;Business &amp; Entrepreneurship&quot;">​</a></h2><ul><li><a href="/general/business.html">Business Resources</a> - Starting a business, resources for veterans</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/general/certifications-and-learning.html">Certifications &amp; Learning</a> - Professional development</li><li><a href="/general/learning.html">Learning Resources</a> - Free education platforms</li><li><a href="/general/funding-certifications-through-the-military.html">Funding Certifications</a> - CA, SEP, TA</li></ul>',49)])])}const p=e(l,[["render",o]]);export{u as __pageData,p as default};
